from pwn import *

# Use objdump to get the table data
r = process(['objdump', '-s', '-j', '.data', '/home/ctfplayer/ctf_files/tablez'])
data = r.recvall().decode()
r.close()

# Parse the hexdump output
trans_tbl = []
for line in data.split('\n'):
    if ' ' not in line:
        continue
    try:
        parts = line.split()
        if len(parts) >= 5:  # Make sure we have enough parts
            hex_values = ''.join(parts[1:5])
            # Convert pairs of hex digits to bytes
            for i in range(0, len(hex_values), 2):
                if i + 1 < len(hex_values):
                    trans_tbl.append(int(hex_values[i:i+2], 16))
    except:
        continue

# Target encrypted string (37 bytes)
target = [
    0xb1, 0xe7, 0x11, 0xf5, 0x9d, 0x73, 0xb3, 0x27,
    0x30, 0xf4, 0xf9, 0xf9, 0xb3, 0x99, 0xbe, 0xb3,
    0xb1, 0x99, 0x65, 0x23, 0x73, 0x99, 0x71, 0x1b,
    0xf9, 0x27, 0x99, 0x23, 0xbe, 0x11, 0x11, 0x65,
    0x65, 0x05, 0x99, 0x23, 0xce
]

# Build reverse mapping from the translation table
reverse_map = {}
for i in range(0, len(trans_tbl), 2):
    if i+1 < len(trans_tbl):
        reverse_map[trans_tbl[i+1]] = trans_tbl[i]

# Decode the flag
flag = ""
for b in target:
    if b in reverse_map:
        flag += chr(reverse_map[b])
