from pwn import *

# Target bytes we want to match (from decompiled main)
target = [
    0xb1, 0xe7, 0x11, 0xf5, 0x9d, 0x73, 0xb3, 0x27,
    0x30, 0xf4, 0xf9, 0xf9, 0xb3, 0x99, 0xbe, 0xb3,
    0xb1, 0x99, 0x65, 0x23, 0x73, 0x99, 0x71, 0x1b,
    0xf9, 0x27, 0x99, 0x23, 0xbe, 0x11, 0x11, 0x65,
    0x65, 0x05, 0x99, 0x23, 0xce
]

# Extract trans_tbl from the binary
p = process(['objdump', '-s', '-j', '.data', '/home/ctfplayer/ctf_files/tablez'])
data = p.recvall().decode()
p.close()

# Parse objdump output to get translation table
trans_tbl = []
for line in data.split('\n'):
    if ' ' not in line:
        continue
    try:
        parts = line.split()
        if len(parts) >= 5:  # Ensure we have enough parts
            hex_values = ''.join(parts[1:5])
            # Convert pairs of hex digits to bytes
            for i in range(0, len(hex_values), 2):
                if i + 1 < len(hex_values):
                    byte = int(hex_values[i:i+2], 16)
                    trans_tbl.append(byte)
    except:
        continue

# Function to find original character for a target byte
def find_original_char(target_byte):
    for i in range(0, len(trans_tbl), 2):
        if i + 1 < len(trans_tbl):
            if trans_tbl[i + 1] == target_byte:
                return chr(trans_tbl[i])
    return '?'

# Decode the flag
flag = ''
for byte in target:
    flag += find_original_char(byte)

print(f"Decoded flag: {flag}")

